import { getFirestore, collection, addDoc, query, where, onSnapshot } from "firebase/firestore";

const db = getFirestore(app);
await addDoc(collection(db, "messages"), {
  text: "hi", uid: auth.currentUser.uid, createdAt: Date.now(),
});

const q = query(collection(db, "messages"), where("uid", "==", auth.currentUser.uid));
onSnapshot(q, (snap) => snap.forEach((doc) => console.log(doc.data())));
